{#- Sampling & Inspection Record for every drawing-based inspection behind this delivery (QI SPEC v2 §4.7). -#}
{%- from "iso_compliance/templates/includes/qi_sampling_record.html" import record, record_styles -%}
{{ record_styles() }}
{%- set ns = namespace(n=0) -%}
{%- for row in doc.items -%}
{%- for rec in dn_records(row) -%}
<div class="{{ 'rp-break' if ns.n }}">{{ record(rec, doc.company) }}</div>
{%- set ns.n = ns.n + 1 -%}
{%- endfor -%}
{%- endfor -%}
{%- if not ns.n -%}
<p style="font-family:Arial,Helvetica,sans-serif;font-size:9pt">No drawing-based inspection stands behind the items on {{ doc.name }}, so there is no sampling and inspection record for it.</p>
{%- endif -%}
